mapper.select:
SELECT COUNT(*)
FROM s_session_slot
WHERE court_id = #{courtId}
  AND status IN ('OPEN', 'HELD', 'BOOKED')
  AND start_at < #{endAt}
  AND end_at > #{startAt}

  AND (weekly_slot_id IS NULL OR weekly_slot_id != #{weeklySlotId})

mapper.update:
UPDATE s_session_slot
SET status = 'CLOSED', updated_at = UTC_TIMESTAMP(3)
WHERE weekly_slot_id = #{weeklySlotId}
  AND status = 'OPEN'
  AND start_at >= #{now}

mapper.select:
SELECT COUNT(*)
FROM s_session_slot
WHERE venue_id = #{venueId}
  AND slot_date = #{date}
  AND status IN ('HELD', 'BOOKED')

mapper.update:
UPDATE s_session_slot
SET status = 'CLOSED', updated_at = UTC_TIMESTAMP(3)
WHERE venue_id = #{venueId}
  AND slot_date = #{date}
  AND status = 'OPEN'
